PREFIX = {"exact-fact": "fact", "exact-term": "term", "vocab-mismatch": "vocab", "ranking": "rank",
          "code": "code", "multi-section": "multi", "unanswerable-oos": "oos", "unanswerable-trap": "trap"}


def build() -> list[dict]:
    rows, per_category = [], {}
    for category, answer_type, question, expected, accept_or_nuggets, gold, evidence, abstain_reason, source in ITEMS:
        n = per_category.get(category, 0)
        per_category[category] = n + 1
        rows.append({
            "id": f"{PREFIX[category]}-{n + 1:03d}",
            "split": "dev" if n % 2 == 0 else "test",      # alternate within each category
            "category": category,
            "answer_type": answer_type,
            "question": question,
            "expected_answer": expected,
            "exact_accept": accept_or_nuggets if answer_type == "exact" else [],
            "nuggets": accept_or_nuggets if answer_type == "open" else [],
            "gold_sections": gold,
            "evidence": evidence,
            "abstain_reason": abstain_reason,
            "corpus_commit": COMMIT,
            "source": source,
            "review": {"status": "draft", "reviewer": "", "note": ""},
        })
    return rows


REVIEW_FIELDS = ["id", "split", "category", "answer_type", "question", "expected_answer", "gold_sections",
                 "decision", "reviewer", "note"]


def apply_reviews(rows: list[dict], review_path: Path) -> None:
    """Merge decisions from the review sheet; create the sheet if it doesn't exist."""
    if not review_path.exists():
        with review_path.open("w", newline="") as f:
            w = csv.DictWriter(f, fieldnames=REVIEW_FIELDS)
            w.writeheader()
            for r in rows:
                w.writerow({**{k: r[k] for k in REVIEW_FIELDS[:6]},
                            "gold_sections": "; ".join(r["gold_sections"]), "decision": "", "reviewer": "", "note": ""})
        return
    with review_path.open(newline="") as f:
        decisions = {row["id"]: row for row in csv.DictReader(f)}
    status = {"approve": "approved", "approved": "approved", "reject": "rejected", "rejected": "rejected"}
    for r in rows:
        d = decisions.get(r["id"])
        if d and d.get("decision", "").strip().lower() in status:
            r["review"] = {"status": status[d["decision"].strip().lower()],
                           "reviewer": d.get("reviewer", "").strip(), "note": d.get("note", "").strip()}


if __name__ == "__main__":
    here = Path(__file__).parent
    rows = build()
    apply_reviews(rows, here / "golden_v1_review.csv")
    (here / "golden_v1.jsonl").write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rows))
    reviewed = sum(r["review"]["status"] != "draft" for r in rows)
    print(f"Wrote {len(rows)} items to {here / 'golden_v1.jsonl'} ({reviewed} reviewed)")
